  ];

  var grid = document.getElementById("grid");
  var noResults = document.getElementById("noResults");
  var searchInput = document.getElementById("searchInput");
  var toast = document.getElementById("toast");
  var themeBtn = document.getElementById("themeBtn");
  var memTheme = "dark";

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function(c) {
      return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c];
    });
  }

  function showToast() {
    toast.classList.add("show");
    clearTimeout(showToast._t);
    showToast._t = setTimeout(function(){ toast.classList.remove("show"); }, 1200);
  }

  function fallbackCopy(url, btn) {
    var ta = document.createElement("textarea");
    ta.value = url;
    ta.style.cssText = "position:fixed;opacity:0";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); showToast(); } catch(e) {}
    document.body.removeChild(ta);
    if (btn) {
      btn.textContent = "OK";
      btn.classList.add("done");
      setTimeout(function(){ btn.textContent = "COPY"; btn.classList.remove("done"); }, 900);
    }
  }

  function render() {
    grid.innerHTML = "";
    DATA.forEach(function(g) {
      var card = document.createElement("div");
      card.className = "group";
      card.dataset.n = g.n.toLowerCase();
      card.dataset.l = g.l.join(" ").toLowerCase();

      var links = "";
      g.l.forEach(function(u) {
        links += '<a class="link" href="' + esc(u) + '" target="_blank" rel="noopener noreferrer" data-u="' + esc(u) + '">' +
                 '<span class="url">' + esc(u.replace(/^https?:\/\//, "")) + '</span>' +
                 '<button class="copy" type="button">COPY</button></a>';
      });

      card.innerHTML =
        '<div class="head">' +
          '<span class="name">' + esc(g.n) + '</span>' +
          '<span><span class="count">' + g.l.length + '</span><span class="chev">▼</span></span>' +
        '</div>' +
        '<div class="body">' + links + '</div>';

      card.querySelector(".head").onclick = function() {
        card.classList.toggle("closed");
      };

      card.querySelectorAll(".copy").forEach(function(btn) {
        btn.onclick = function(e) {
          e.preventDefault();
          e.stopPropagation();
          var url = btn.closest(".link").dataset.u;
          try {
            if (navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(url).then(function() {
                btn.textContent = "OK";
                btn.classList.add("done");
                showToast();
                setTimeout(function(){ btn.textContent = "COPY"; btn.classList.remove("done"); }, 900);
              }).catch(function(){ fallbackCopy(url, btn); });
            } else {
              fallbackCopy(url, btn);
            }
          } catch (err) {
            fallbackCopy(url, btn);
          }
        };
      });

      grid.appendChild(card);
    });
  }

  function filter(q) {
    q = (q || "").trim().toLowerCase();
    var any = false;
    document.querySelectorAll(".group").forEach(function(c) {
      var match = !q || c.dataset.n.indexOf(q) !== -1 || c.dataset.l.indexOf(q) !== -1;
      if (match) {
        c.classList.remove("hide");
        any = true;
      } else {
        c.classList.add("hide");
      }
    });
    noResults.classList.toggle("show", !any);
  }

  if (searchInput) {
    searchInput.oninput = function(e) { filter(e.target.value); };
  }

  document.addEventListener("keydown", function(e) {
    if (e.key === "/" && document.activeElement !== searchInput) {
      e.preventDefault();
      searchInput.focus();
    }
  });

  try { memTheme = localStorage.getItem("th") || "dark"; } catch(e) {}
  document.documentElement.setAttribute("data-th", memTheme);

  if (themeBtn) {
    themeBtn.onclick = function() {
      var next = document.documentElement.getAttribute("data-th") === "dark" ? "light" : "dark";
      document.documentElement.setAttribute("data-th", next);
      try { localStorage.setItem("th", next); } catch(e) {}
    };
  }

  render();
})();
